module.exports = function withIosDeploymentTargetFix(config) {
  console.log('IOS DEPLOYMENT TARGET PLUGIN LOADED');
  const { withDangerousMod } = require('expo/config-plugins');
  const fs = require('fs');
  const path = require('path');
  return withDangerousMod(config, 'ios', async (config) => {
    console.log('IOS DEPLOYMENT TARGET PLUGIN ACTION');
    const podfilePath = path.join(config.modRequest.platformProjectRoot, 'Podfile');
    console.log('PODFILE PATH', podfilePath);
    let podfile = fs.readFileSync(podfilePath, 'utf8');
    const hook = `
  # --- generated by withIosDeploymentTargetFix ---
  installer.pods_project.targets.each do |target|
    target.build_configurations.each do |bc|
      current = bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
      if current && Gem::Version.new(current) < Gem::Version.new('15.1')
        bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '15.1'
      end
    end
  end
  # --- end withIosDeploymentTargetFix ---`;
    const marker = 'post_install do |installer|';
    if (!podfile.includes('withIosDeploymentTargetFix')) {
      podfile = podfile.replace(marker, `${marker}\n${hook}`);
      fs.writeFileSync(podfilePath, podfile);
      console.log('PODFILE PATCHED');
    }
    return config;
  });
};
